const raw = $input.first().json;
let payload = raw.body !== undefined ? raw.body : raw;
if (typeof payload === 'string') {
  try {
    payload = JSON.parse(payload);
  } catch (e) {
    return [{ json: { valid: false, spam: false, error: 'Invalid JSON body string' } }];
  }
}
if (!payload || typeof payload !== 'object') {
  return [{ json: { valid: false, spam: false, error: 'Request body must be a JSON object' } }];
}

// Honeypot spam check
if (payload.website && String(payload.website).trim() !== '') {
  return [{ json: { valid: false, spam: true, error: null } }];
}

const comment = typeof payload.comment === 'string' ? payload.comment.trim() : '';
if (comment.length < 3 || comment.length > 2000) {
  return [{ json: { valid: false, spam: false, error: 'Comment is required and must be between 3 and 2000 characters' } }];
}

let rating = null;
if (payload.rating !== undefined && payload.rating !== null && payload.rating !== '') {
  const r = Number(payload.rating);
  if (!Number.isInteger(r) || r < 1 || r > 5) {
    return [{ json: { valid: false, spam: false, error: 'Rating must be an integer between 1 and 5' } }];
  }
  rating = r;
}

const validSources = ['survey', 'email', 'google_review', 'test'];
let source = typeof payload.source === 'string' ? payload.source.trim().toLowerCase() : 'survey';
if (!validSources.includes(source)) {
  source = 'survey';
}

const id = 'fb_' + Date.now().toString(36) + '_' + Math.random().toString(36).slice(2, 8);
const received_at = new Date().toISOString();

const data = {
  id,
  received_at,
  source,
  source_ref: typeof payload.source_ref === 'string' ? payload.source_ref.trim() : '',
  customer_name: typeof payload.customer_name === 'string' ? payload.customer_name.trim() : '',
  customer_email: typeof payload.customer_email === 'string' ? payload.customer_email.trim() : '',
  rating,
  comment,
  batch_id: typeof payload.batch_id === 'string' ? payload.batch_id.trim() : ''
};

return [{ json: { valid: true, spam: false, error: null, data } }];

const validated = $('Validate Input').first().json.data;
const sheetRows = $input.all();
const existingGroupsSet = new Set();

for (const row of sheetRows) {
  const g = row.json?.issue_group;
  if (g && typeof g === 'string') {
    const clean = g.trim().toLowerCase();
    if (clean !== '' && clean !== 'untriaged') {
      existingGroupsSet.add(clean);
    }
  }
}
const existingGroups = Array.from(existingGroupsSet);

const prompt = `You are a customer feedback analyst for a business. Classify ONE customer comment.

Rules:
- category: exactly one of
  - "bug": a technical malfunction of the app or website (crash, freeze, error message, broken button, payment page failing).
  - "complaint": dissatisfaction with service, delivery, staff, price, food or product quality.
  - "idea": a suggestion or feature request.
  - "praise": positive feedback with no problem reported.
- sentiment: "positive", "neutral" or "negative".
- sentiment_score: a number from -1 (very negative) to 1 (very positive).
- is_angry: true ONLY for strong anger: insults, threats to leave, report or sue, words like "furious", "worst", "scam", "disgusting", heavy use of capitals or "!!!". Mild disappointment is NOT angry.
- issue_group: for complaint, bug and idea, a short lowercase noun phrase of 2 to 4 words naming the UNDERLYING problem in generic terms (good: "slow delivery"; bad: "order 4451 was late on friday").
  You MUST reuse a group from EXISTING GROUPS when the comment describes the same underlying problem, even if worded differently.
  Create a new group only when none fits. For praise, use "".
- Key Group Distinctions:
  * Receiving the wrong meal, different items, or missing food MUST be grouped under "wrong order" (never confuse with "food quality").
  * App crashes, freezes, or checkout closing MUST be grouped under "app crashes".
  * Delayed rider, food arriving late, or long wait MUST be grouped under "slow delivery".
  * Rude agents, insults, shouting, or disrespectful attitude MUST be grouped under "rude support".
  * High prices, expensive dishes, or excessive delivery fees MUST be grouped under "high price".
- summary: at most 15 words, neutral tone.

EXISTING GROUPS: ${JSON.stringify(existingGroups)}
CUSTOMER RATING (1-5, may be empty): ${validated.rating !== null ? validated.rating : ''}
COMMENT:
"""${validated.comment}"""`;

const schema = {
  type: "OBJECT",
  required: ["category", "sentiment", "sentiment_score", "is_angry", "issue_group", "summary"],
  properties: {
    category: { type: "STRING", enum: ["praise", "complaint", "bug", "idea"] },
    sentiment: { type: "STRING", enum: ["positive", "neutral", "negative"] },
    sentiment_score: { type: "NUMBER" },
    is_angry: { type: "BOOLEAN" },
    issue_group: { type: "STRING" },
    summary: { type: "STRING" }
  }
};

const geminiPayload = {
  contents: [
    {
      parts: [
        { text: prompt }
      ]
    }
  ],
  generationConfig: {
    temperature: 0.1,
    responseMimeType: "application/json",
    responseSchema: schema
  }
};

return [{
  json: {
    validated,
    existingGroups,
    geminiPayload
  }
}];

const validated = $('Build Gemini Request').first().json.validated;
const existingGroups = $('Build Gemini Request').first().json.existingGroups || [];
const ANGRY_THRESHOLD = -0.85;

function jaccardSimilarity(str1, str2) {
  const set1 = new Set(str1.toLowerCase().split(/\s+/).filter(Boolean));
  const set2 = new Set(str2.toLowerCase().split(/\s+/).filter(Boolean));
  if (set1.size === 0 || set2.size === 0) return 0;
  let intersection = 0;
  for (const item of set1) {
    if (set2.has(item)) intersection++;
  }
  const union = new Set([...set1, ...set2]).size;
  return intersection / union;
}

let aiData = null;
const geminiResponse = $input.first().json;

try {
  const text = geminiResponse.candidates?.[0]?.content?.parts?.[0]?.text;
  if (text) {
    aiData = JSON.parse(text);
  }
} catch (e) {
  aiData = null;
}

let category, sentiment, sentiment_score, is_angry, issue_group, summary;

if (aiData && typeof aiData === 'object') {
  const validCats = ['praise', 'complaint', 'bug', 'idea'];
  let rawScore = typeof aiData.sentiment_score === 'number' ? aiData.sentiment_score : 0;
  sentiment_score = Math.max(-1, Math.min(1, Math.round(rawScore * 100) / 100));

  if (validCats.includes(aiData.category)) {
    category = aiData.category;
  } else {
    category = sentiment_score < 0 ? 'complaint' : 'praise';
  }

  const validSents = ['positive', 'neutral', 'negative'];
  sentiment = validSents.includes(aiData.sentiment) ? aiData.sentiment : (sentiment_score > 0.1 ? 'positive' : sentiment_score < -0.1 ? 'negative' : 'neutral');

  if (category === 'praise') {
    issue_group = '';
  } else {
    let rawGroup = typeof aiData.issue_group === 'string' ? aiData.issue_group : '';
    let normalized = rawGroup.toLowerCase().replace(/[^a-z0-9\s]/g, ' ').replace(/\s+/g, ' ').trim();

    let matchedGroup = normalized;
    for (const existing of existingGroups) {
      if (jaccardSimilarity(normalized, existing) >= 0.5) {
        matchedGroup = existing;
        break;
      }
    }
    issue_group = matchedGroup || 'general feedback';
  }

  is_angry = (aiData.is_angry === true || sentiment_score <= ANGRY_THRESHOLD) && category !== 'praise';
  summary = typeof aiData.summary === 'string' ? aiData.summary.trim() : '';
  if (summary.split(/\s+/).length > 15) {
    summary = summary.split(/\s+/).slice(0, 15).join(' ');
  }
} else {
  const r = validated.rating || 3;
  if (r >= 4) {
    category = 'praise';
    sentiment = 'positive';
    sentiment_score = 0.8;
    issue_group = '';
  } else if (r <= 2) {
    category = 'complaint';
    sentiment = 'negative';
    sentiment_score = -0.8;
    issue_group = 'untriaged';
  } else {
    category = 'idea';
    sentiment = 'neutral';
    sentiment_score = 0.0;
    issue_group = 'untriaged';
  }
  is_angry = false;
  summary = 'AI unavailable; classified by rating.';
}

const row = {
  id: validated.id,
  received_at: validated.received_at,
  source: validated.source,
  source_ref: validated.source_ref,
  customer_name: validated.customer_name,
  customer_email: validated.customer_email,
  rating: validated.rating !== null ? validated.rating : '',
  comment: validated.comment,
  category,
  sentiment,
  sentiment_score,
  is_angry: is_angry ? 'TRUE' : 'FALSE',
  issue_group,
  summary,
  alert_sent: is_angry ? 'TRUE' : 'FALSE',
  batch_id: validated.batch_id
};

return [{
  json: {
    ...row,
    is_angry_bool: is_angry
  }
}];

